"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[6253],{8362(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>l,default:()=>p,frontMatter:()=>c,metadata:()=>s,toc:()=>u});const s=JSON.parse('{"id":"part2-backend-platform-security/github-governance","title":"GitHub Governance: Rulesets, Workflows, Runners, and Enforcement","description":"A practical admin guide explaining what runs, who runs it, where it runs, and how GitHub blocks merges/pushes when policy is not satisfied.","source":"@site/docs/part2-backend-platform-security/14-github-governance.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/14-github-governance","permalink":"/tutorials/part2-backend-platform-security/14-github-governance","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":14,"frontMatter":{"title":"GitHub Governance: Rulesets, Workflows, Runners, and Enforcement","slug":"/part2-backend-platform-security/14-github-governance","description":"A practical admin guide explaining what runs, who runs it, where it runs, and how GitHub blocks merges/pushes when policy is not satisfied.","sidebar_label":"16. GitHub governance and CI","pagination_label":"16. GitHub governance and CI","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"15. Cross-cloud service integration","permalink":"/tutorials/part2-backend-platform-security/13-external-service-integration"},"next":{"title":"Part overview","permalink":"/tutorials/part3-agent-protocols/overview"}}');var o=t(4848),r=t(8453),i=t(8172);const a=JSON.parse('{"sourcePath":"part2-backend-platform-security/14-github-governance.html","route":"/part2-backend-platform-security/14-github-governance","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"GitHub Governance: Rulesets, Actions Workflows, Runners, and Enforcement","title":"GitHub Governance: Rulesets, Workflows, Runners, and Enforcement","description":"A practical admin guide explaining what runs, who runs it, where it runs, and how GitHub blocks merges/pushes when policy is not satisfied.","readingMinutes":11,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-the-admin-mental-model-the-plumbing-most-important","label":"1) The admin mental model (the \u201cplumbing\u201d) most important"},{"id":"2-git-vs-github-governance-what-each-can-can-t-enforce","label":"2) Git vs GitHub governance (what each can/can\u2019t enforce)"},{"id":"3-workflows-and-actions-how-github-knows-what-to-run","label":"3) Workflows and actions (how GitHub knows what to run)"},{"id":"4-status-checks-what-the-ruleset-actually-reads","label":"4) Status checks (what the ruleset actually reads)"},{"id":"5-rulesets-what-they-enforce-and-why-they-don-t-run-tools","label":"5) Rulesets (what they enforce and why they don\u2019t \u201crun tools\u201d)"},{"id":"6-required-checks-vs-required-workflows-enterprise-scale","label":"6) Required checks vs Required workflows (enterprise scale)"},{"id":"7-aqua-trivy-example-scan-workflow-merge-enforcement","label":"7) Aqua/Trivy example (scan workflow + merge enforcement)"},{"id":"8-push-controls-naming-direct-pushes-secrets","label":"8) Push controls (naming, direct pushes, secrets)"},{"id":"9-runners-hosted-vs-self-hosted-and-runner-security","label":"9) Runners (hosted vs self-hosted) and runner security"},{"id":"10-enterprise-wide-patterns-recommended-setup","label":"10) Enterprise-wide patterns (recommended setup)"},{"id":"11-troubleshooting-as-an-admin","label":"11) Troubleshooting as an admin"},{"id":"12-copy-paste-templates","label":"12) Copy/paste templates"}],"html":"<header>\\n  <div class=\\"wrap\\">\\n    \\n    <p class=\\"sub\\">\\n      A practical admin guide explaining <strong>what runs</strong>, <strong>who runs it</strong>, <strong>where it runs</strong>,\\n      and <strong>how GitHub blocks merges/pushes</strong> when policy is not satisfied.\\n    </p>\\n\\n    <nav aria-label=\\"Table of contents\\">\\n      <strong>Contents</strong>\\n      <ul>\\n        <li><a href=\\"#mentalmodel\\">1) The admin mental model (the \u201cplumbing\u201d)</a></li>\\n        <li><a href=\\"#git-vs-github\\">2) Git vs GitHub governance (what each can/can\u2019t enforce)</a></li>\\n        <li><a href=\\"#workflows\\">3) Workflows and actions (how GitHub knows what to run)</a></li>\\n        <li><a href=\\"#checks\\">4) Status checks (what the ruleset actually reads)</a></li>\\n        <li><a href=\\"#rulesets\\">5) Rulesets (what they enforce and why they don\u2019t \u201crun tools\u201d)</a></li>\\n        <li><a href=\\"#required-workflows\\">6) Required checks vs Required workflows (enterprise scale)</a></li>\\n        <li><a href=\\"#aqua\\">7) Aqua/Trivy example (scan workflow + merge enforcement)</a></li>\\n        <li><a href=\\"#push-controls\\">8) Push controls (naming, direct pushes, secrets)</a></li>\\n        <li><a href=\\"#runners\\">9) Runners (hosted vs self-hosted) and runner security</a></li>\\n        <li><a href=\\"#enterprise\\">10) Enterprise-wide patterns (recommended setup)</a></li>\\n        <li><a href=\\"#troubleshooting\\">11) Troubleshooting as an admin</a></li>\\n        <li><a href=\\"#templates\\">12) Copy/paste templates</a></li>\\n      </ul>\\n    </nav>\\n  </div>\\n</header>\\n\\n<main class=\\"wrap\\">\\n\\n  <section id=\\"mentalmodel\\">\\n    <h2 id=\\"1-the-admin-mental-model-the-plumbing-most-important\\">1) The admin mental model (the \u201cplumbing\u201d) <span class=\\"pill\\">most important</span></h2>\\n\\n    <p>\\n      Think of GitHub governance like a gated building:\\n      <strong>workflows produce evidence</strong> (passes/fails) and <strong>rulesets are the bouncer</strong>.\\n      The bouncer does not do the inspection themselves; they only check the evidence before letting someone in.\\n    </p>\\n\\n    <div class=\\"box ok\\">\\n      <p><strong>Four building blocks you should memorize:</strong></p>\\n      <ul>\\n        <li><strong>Workflow</strong>: the script that defines what to do (run tests, scan code, etc.) and when to do it.</li>\\n        <li><strong>Runner</strong>: the machine that executes workflow jobs.</li>\\n        <li><strong>Status check</strong>: the recorded outcome from the workflow job (pass/fail) attached to a commit/PR.</li>\\n        <li><strong>Ruleset</strong>: the policy gate that blocks merge/push if conditions aren\u2019t met.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box warn\\">\\n      <p><strong>Key clarification:</strong> If you type <code>aqua-trivy-scan</code> into a ruleset, you are not \u201cturning on Aqua\u201d.</p>\\n      <p>\\n        You are saying: <em>\u201cI expect a check with this name to exist and be passing.\u201d</em>\\n        Someone/something must create that check\u2014usually a workflow file in the repository or a GitHub App integration.\\n      </p>\\n    </div>\\n\\n    <div class=\\"callout\\">\\n      <p class=\\"tiny\\"><strong>Admin perspective:</strong> Your job is to ensure (1) the right workflows exist and run on the right events, and (2) the ruleset requires the correct checks and restricts bypass.</p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"git-vs-github\\">\\n    <h2 id=\\"2-git-vs-github-governance-what-each-can-can-t-enforce\\">2) Git vs GitHub governance (what each can/can\u2019t enforce)</h2>\\n\\n    <p>\\n      This matters because people often say \u201cGit should block X\u201d. In reality:\\n      <strong>Git is the version control system</strong>, while <strong>GitHub is the policy and automation platform</strong>.\\n    </p>\\n\\n    <div class=\\"grid\\">\\n      <div class=\\"box\\">\\n        <h3 id=\\"git-alone\\">Git (alone)</h3>\\n        <p>\\n          Git controls commits/branches and lets you push/fetch. It can run optional local hooks, but those are not reliable for enforcement\\n          because users can bypass them. Git itself does not understand \u201ctests passed\u201d or \u201cscan passed\u201d across a company.\\n        </p>\\n        <ul>\\n          <li>Good for: history, branching, collaboration primitives.</li>\\n          <li>Not good for: enterprise policy enforcement of scans/tests.</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <h3 id=\\"github-platform\\">GitHub (platform)</h3>\\n        <p>\\n          GitHub adds PRs, reviews, checks, and enforcement. This is where administrators set rules and apply them across repositories.\\n        </p>\\n        <ul>\\n          <li>PR process: reviews, approvals, merge strategies.</li>\\n          <li>Automation: GitHub Actions workflows.</li>\\n          <li>Governance: rulesets, required checks/workflows, branch restrictions.</li>\\n        </ul>\\n      </div>\\n    </div>\\n  </section>\\n\\n  <section id=\\"workflows\\">\\n    <h2 id=\\"3-workflows-and-actions-how-github-knows-what-to-run\\">3) Workflows and actions (how GitHub knows what to run)</h2>\\n\\n    <p>\\n      GitHub Actions is configured by YAML files stored in the repository at <code>.github/workflows/*.yml</code>.\\n      GitHub watches for specific events (like PR updates or pushes). When an event occurs, GitHub checks:\\n      \u201cDo I have any workflows whose <code>on:</code> section matches this event?\u201d If yes, those workflows are scheduled to run.\\n    </p>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"workflow-anatomy\\">Workflow anatomy</h3>\\n      <table aria-label=\\"Actions glossary\\">\\n        <thead>\\n          <tr><th>Term</th><th>Plain English</th><th>Why admins care</th></tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>Workflow</strong></td>\\n            <td>A set of jobs triggered by events.</td>\\n            <td>Defines what will run (or not run) for a PR/push.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Job</strong></td>\\n            <td>Runs on one runner; contains steps.</td>\\n            <td>Each job produces a check result; required checks often match job names.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Step</strong></td>\\n            <td>One action call (<code>uses</code>) or one shell command (<code>run</code>).</td>\\n            <td>Steps are where tools run; failures here fail the job/check.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Action</strong></td>\\n            <td>Reusable unit referenced via <code>uses: owner/repo@ref</code>.</td>\\n            <td>This is how you \u201cbring in\u201d scanners like Trivy/Aqua into workflows.</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Runner</strong></td>\\n            <td>The compute that executes the job.</td>\\n            <td>Admins control runner availability, security, and who can use them.</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div class=\\"box\\">\\n      <h3 id=\\"how-is-that-container-tool-found-your-earlier-question\\">\u201cHow is that container/tool found?\u201d (your earlier question)</h3>\\n      <p>\\n        In a workflow, a line such as\\n        <code>uses: aquasecurity/trivy-action@ed142fd0673e97e23eac54620cfb913e5ce36c25</code>\\n        is an explicit pointer to an Action repository and immutable commit.\\n        GitHub fetches that action and runs it. If the action is Docker-based, its own <code>action.yml</code> defines the container image.\\n        If it is composite-based, it runs commands directly on the runner (often installing Trivy and executing it).\\n      </p>\\n      <p class=\\"tiny\\">\\n        Keep a version comment such as <code># v0.36.0</code> beside the SHA so\\n        update tools and reviewers retain context. GitHub can enforce\\n        full-length SHA pins at repository or organization level. Use\\n        Dependabot or another reviewed update process to advance those SHAs,\\n        and restrict which actions are allowed through organization or\\n        enterprise policy.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"checks\\">\\n    <h2 id=\\"4-status-checks-what-the-ruleset-actually-reads\\">4) Status checks (what the ruleset actually reads)</h2>\\n\\n    <p>\\n      A <strong>status check</strong> is a named pass/fail result attached to a commit and shown on the PR.\\n      When a job finishes, GitHub records the result. Rulesets don\u2019t inspect your code; they simply check\\n      whether the required check names are present and successful.\\n    </p>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"how-check-names-are-typically-formed\\">How check names are typically formed</h3>\\n      <p>\\n        The UI usually shows checks as <strong><code>&lt;workflow name&gt; / &lt;job name&gt;</code></strong>.\\n        Example: workflow name <code>aqua-trivy-scan</code> with job name <code>scan</code> \u2192 check appears as <code>aqua-trivy-scan / scan</code>.\\n      </p>\\n    </div>\\n\\n    <div class=\\"box warn\\">\\n      <h3 id=\\"why-admins-often-get-stuck\\">Why admins often get \u201cstuck\u201d</h3>\\n      <ul>\\n        <li>They require <code>aqua-trivy-scan</code> but the real check is <code>aqua-trivy-scan / scan</code>.</li>\\n        <li>The workflow doesn\u2019t run on <code>pull_request</code>, so PRs never get that check.</li>\\n        <li>Actions are disabled by org policy, so checks never run.</li>\\n        <li>The check exists, but the job is \u201cskipped\u201d due to workflow conditions.</li>\\n      </ul>\\n      <p class=\\"tiny\\">Admin practice: always read the PR \u201cChecks\u201d list and copy the exact check name to your ruleset.</p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"rulesets\\">\\n    <h2 id=\\"5-rulesets-what-they-enforce-and-why-they-don-t-run-tools\\">5) Rulesets (what they enforce and why they don\u2019t \u201crun tools\u201d)</h2>\\n\\n    <p>\\n      A ruleset is a server-side enforcement policy attached to branch targets (e.g., <code>main</code> or <code>release/*</code>).\\n      It can block pushes, block merges, require approvals, require checks, and more.\\n      But it does not run scanners or execute workflows; it only evaluates the recorded states of checks and PR requirements.\\n    </p>\\n\\n    <div class=\\"grid\\">\\n      <div class=\\"box ok\\">\\n        <h3 id=\\"rulesets-can-enforce\\">Rulesets can enforce</h3>\\n        <ul>\\n          <li>Require PRs (no direct merge)</li>\\n          <li>Require approvals / code owners</li>\\n          <li>Require status checks to pass</li>\\n          <li>Restrict direct pushes / force pushes</li>\\n          <li>Restrict branch creation/updates (naming patterns)</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box bad\\">\\n        <h3 id=\\"rulesets-cannot-do-by-themselves\\">Rulesets cannot do by themselves</h3>\\n        <ul>\\n          <li>Install tools like Aqua/Trivy</li>\\n          <li>Decide what to run without workflows or required-workflow feature</li>\\n          <li>Produce a check result without something executing</li>\\n        </ul>\\n      </div>\\n    </div>\\n\\n    <div class=\\"box\\">\\n      <h3 id=\\"what-this-means-for-your-aqua-enforcement-requirement\\">What this means for your \u201cAqua enforcement\u201d requirement</h3>\\n      <p>\\n        You must have a workflow (or required workflow) that performs the Aqua scan and fails if policy is violated.\\n        Then the ruleset requires the check to be green before merge.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"required-workflows\\">\\n    <h2 id=\\"6-required-checks-vs-required-workflows-enterprise-scale\\">6) Required checks vs Required workflows (enterprise scale)</h2>\\n\\n    <p>\\n      There are two ways to enforce scanning outcomes with rulesets. They look similar but behave differently:\\n    </p>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"required-checks-most-common\\">Required checks (most common)</h3>\\n      <p>\\n        You list a check name (e.g., <code>aqua-trivy-scan / scan</code>) and GitHub blocks merges until that check is successful.\\n        This relies on each repo (or a shared reusable workflow) producing the same check name.\\n      </p>\\n      <ul>\\n        <li>Pros: simple, widely used, clear in PR UI.</li>\\n        <li>Cons: requires standardization; check name drift causes broken merges.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"required-workflows-better-for-enterprise-governance\\">Required workflows (better for enterprise governance)</h3>\\n      <p>\\n        Instead of requiring a \u201cname that must appear\u201d, you require a specific workflow to run.\\n        This is useful when you want centralized enforcement and fewer per-repo variations.\\n      </p>\\n      <ul>\\n        <li>Pros: less drift; admins can enforce a standard baseline.</li>\\n        <li>Cons: still requires Actions to be enabled and configured for the targeted repos.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box warn\\">\\n      <p>\\n        <strong>Practical admin advice:</strong> use required workflows for the baseline (security + compliance),\\n        and required checks for additional repo-specific checks.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"aqua\\">\\n    <h2 id=\\"7-aqua-trivy-example-scan-workflow-merge-enforcement\\">7) Aqua/Trivy example (scan workflow + merge enforcement)</h2>\\n\\n    <p>\\n      Below is a concrete \u201cend-to-end\u201d example: the workflow produces a scan check, and the ruleset blocks merges if it fails.\\n      The workflow must <strong>fail</strong> when policy is violated; that failure becomes the red status check.\\n    </p>\\n\\n    <h3 id=\\"7-1-workflow-run-trivy-aqua-and-fail-on-high-critical\\">7.1 Workflow: run Trivy (Aqua) and fail on HIGH/CRITICAL</h3>\\n    <p>Create: <code>.github/workflows/aqua-trivy-scan.yml</code></p>\\n\\n    <pre><code>name: aqua-trivy-scan\\n\\non:\\n  pull_request:\\n  push:\\n    branches: [ \\"main\\" ]\\n\\npermissions:\\n  contents: read\\n\\njobs:\\n  scan:\\n    name: scan\\n    runs-on: ubuntu-24.04\\n    steps:\\n      - name: Checkout\\n        uses: actions/checkout@de0fac2e4500dabe0009e67214ff5f5447ce83dd  # v6.0.2\\n\\n      - name: Trivy filesystem scan (fail on HIGH/CRITICAL)\\n        uses: aquasecurity/trivy-action@ed142fd0673e97e23eac54620cfb913e5ce36c25  # v0.36.0\\n        with:\\n          scan-type: fs\\n          scan-ref: .\\n          severity: HIGH,CRITICAL\\n          ignore-unfixed: true\\n          format: table\\n          exit-code: 1</code></pre>\\n\\n    <div class=\\"box bad\\">\\n      <h3 id=\\"why-the-sha-pin-is-a-security-control-not-cosmetic\\">Why the SHA pin is a security control, not cosmetic</h3>\\n      <p>\\n        Aqua\'s March 2026 advisory records a temporary compromise in which\\n        many historical <code>trivy-action</code> tags were force-pushed to\\n        malicious commits. Versions before <code>0.35.0</code> are listed as\\n        affected; the older <code>v0.24.0</code> example previously shown in\\n        this chapter must not be restored. A full commit SHA cannot move when\\n        a tag moves. If the affected action ran during the advisory\'s exposure\\n        window, follow the vendor\'s incident-response guidance and rotate any\\n        credentials available to that job.\\n      </p>\\n    </div>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"what-check-appears-in-the-pr\\">What check appears in the PR?</h3>\\n      <p>Typically: <code>aqua-trivy-scan / scan</code>. That is the string you require in the ruleset.</p>\\n    </div>\\n\\n    <h3 id=\\"7-2-ruleset-block-merge-to-main-unless-the-scan-check-is-green\\">7.2 Ruleset: block merge to main unless the scan check is green</h3>\\n    <ul>\\n      <li>Create/edit a ruleset targeting branch: <code>main</code>.</li>\\n      <li>Enable \u201cRequire a pull request\u201d.</li>\\n      <li>Enable \u201cRequire status checks to pass\u201d.</li>\\n      <li>Select <code>aqua-trivy-scan / scan</code> as a required check.</li>\\n      <li>Disable direct pushes to <code>main</code> (recommended).</li>\\n    </ul>\\n\\n    <div class=\\"box warn\\">\\n      <p>\\n        <strong>Why must the workflow exist?</strong> Because the ruleset only checks for the recorded status check.\\n        If there is no workflow producing <code>aqua-trivy-scan / scan</code>, the ruleset has no green check to verify\u2014merge stays blocked.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"push-controls\\">\\n    <h2 id=\\"8-push-controls-naming-direct-pushes-secrets\\">8) Push controls (naming, direct pushes, secrets)</h2>\\n\\n    <p>\\n      \u201cPush-time enforcement\u201d means blocking a push before it lands in the repository history.\\n      GitHub can do this strongly for a few categories; for heavier scans, the common pattern is merge gating.\\n    </p>\\n\\n    <div class=\\"grid\\">\\n      <div class=\\"box ok\\">\\n        <h3 id=\\"strong-push-time-controls\\">Strong push-time controls</h3>\\n        <ul>\\n          <li><strong>Block direct pushes</strong> to protected branches (via ruleset).</li>\\n          <li><strong>Branch naming restrictions</strong> (allow only certain patterns).</li>\\n          <li><strong>Secret push protection</strong> (block pushes containing detected secrets).</li>\\n        </ul>\\n      </div>\\n      <div class=\\"box warn\\">\\n        <h3 id=\\"why-not-push-gate-everything\\">Why not push-gate everything?</h3>\\n        <p>\\n          Many scans take time (minutes). Push rejection must be near-instant and synchronous.\\n          Therefore, organizations usually enforce \u201cheavy scanning\u201d at merge time (required checks) and keep push-time controls\\n          for fast, deterministic rules (naming, protected branches, secret push protection).\\n        </p>\\n      </div>\\n    </div>\\n\\n    <h3 id=\\"branch-naming-enforcement-example\\">Branch naming enforcement example</h3>\\n    <p>As an admin, you typically allow only patterns like:</p>\\n    <pre><code>feature/*\\nbugfix/*\\nhotfix/*\\nchore/*\\nrelease/*</code></pre>\\n\\n    <p class=\\"tiny\\">\\n      Note: In GitHub, rulesets often work by targeting patterns and restricting create/update. You configure allowed patterns by restricting broadly and\\n      explicitly permitting specific patterns (depending on your chosen ruleset approach).\\n    </p>\\n  </section>\\n\\n  <section id=\\"runners\\">\\n    <h2 id=\\"9-runners-hosted-vs-self-hosted-and-runner-security\\">9) Runners (hosted vs self-hosted) and runner security</h2>\\n\\n    <p>\\n      A runner is the execution environment for jobs. If someone can run code on a runner, they effectively execute arbitrary commands in that environment.\\n      That\u2019s why runner governance (which repos can use which runners) is a core admin responsibility.\\n    </p>\\n\\n    <div class=\\"grid\\">\\n      <div class=\\"box\\">\\n        <h3 id=\\"github-hosted-runners\\">GitHub-hosted runners</h3>\\n        <p>\\n          GitHub manages them; they are generally ephemeral and reset between jobs. This reduces persistence risk.\\n          Great default for most repos and for consistent environments.\\n        </p>\\n        <ul>\\n          <li>Select a specific image such as <code>runs-on: ubuntu-24.04</code> when reproducibility matters; <code>ubuntu-latest</code> is convenient but can move.</li>\\n          <li>Minimal operational work for admins</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <h3 id=\\"self-hosted-runners\\">Self-hosted runners</h3>\\n        <p>\\n          You manage the machines (VMs/on-prem/Kubernetes). Choose these when you need strict network access, specialized tools, or compliance controls.\\n          However, you must treat them as sensitive and isolate them from untrusted workloads.\\n        </p>\\n        <ul>\\n          <li>Select with labels: <code>runs-on: [self-hosted, linux, x64, secure]</code></li>\\n          <li>Admins should use runner groups to restrict usage</li>\\n        </ul>\\n      </div>\\n    </div>\\n\\n    <div class=\\"box bad\\">\\n      <h3 id=\\"self-hosted-runner-security-short-practical\\">Self-hosted runner security (short, practical)</h3>\\n      <ul>\\n        <li>Use <strong>runner groups</strong> and allow only selected repos.</li>\\n        <li>Keep a \u201csecure\u201d runner group for sensitive repos; do not allow broad access.</li>\\n        <li>Prefer <strong>ephemeral runners</strong> (one job \u2192 destroy) for high-security posture.</li>\\n        <li>Do not allow fork PRs or untrusted code to run on sensitive runners.</li>\\n        <li>Minimize secrets exposure; assume workflow-exposed secrets can be exfiltrated.</li>\\n      </ul>\\n    </div>\\n  </section>\\n\\n  <section id=\\"enterprise\\">\\n    <h2 id=\\"10-enterprise-wide-patterns-recommended-setup\\">10) Enterprise-wide patterns (recommended setup)</h2>\\n\\n    <p>\\n      Enterprise governance works best when you standardize:\\n      workflow names, job names, required checks, and who can bypass rulesets.\\n      Your goal is to make compliance \u201cboring\u201d and predictable.\\n    </p>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"recommended-enterprise-baseline\\">Recommended enterprise baseline</h3>\\n      <ul>\\n        <li><strong>Enterprise ruleset</strong> applied to protected branches (e.g., <code>main</code>, <code>release/*</code>).</li>\\n        <li><strong>Require PR</strong> + <strong>require approvals</strong> (optional based on policy).</li>\\n        <li><strong>Require checks</strong>: tests + scan checks (<code>aqua-trivy-scan / scan</code>).</li>\\n        <li><strong>Block direct pushes</strong> to protected branches.</li>\\n        <li><strong>Branch naming restriction</strong> (limit branch creation/update patterns).</li>\\n        <li><strong>Secret push protection</strong> enabled org/enterprise-wide.</li>\\n        <li><strong>Full-length action SHA policy</strong> enabled, with automated update PRs and review.</li>\\n        <li><strong><code>CODEOWNERS</code> review</strong> required for <code>.github/workflows/</code> and governance files.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"scaling-tip-required-workflows\\">Scaling tip: required workflows</h3>\\n      <p>\\n        If you can use required workflows, centralize the baseline scanning workflow so every repo gets the same scanning behavior and check naming.\\n        This reduces drift and makes rulesets more stable.\\n      </p>\\n    </div>\\n\\n    <div class=\\"box ok\\">\\n      <h3 id=\\"cloud-deployments-oidc-instead-of-stored-cloud-keys\\">Cloud deployments: OIDC instead of stored cloud keys</h3>\\n      <p>\\n        Give the job <code>id-token: write</code>, exchange GitHub\'s\\n        short-lived OIDC token with the cloud provider, and constrain the\\n        provider trust policy by <code>aud</code> and <code>sub</code>. Do not\\n        trust every workflow in an organization. Where appropriate, also bind\\n        the reusable workflow through <code>job_workflow_ref</code>, repository\\n        ID, environment, or custom repository-property claims.\\n      </p>\\n      <p>\\n        Repositories created after July 15, 2026 use GitHub\'s immutable\\n        default <code>sub</code> format containing owner and repository IDs;\\n        older repositories keep the name-based format until opted in. Migrate\\n        the cloud trust policy before opting in so deployments do not fail.\\n      </p>\\n    </div>\\n\\n    <div class=\\"box\\">\\n      <h3 id=\\"build-provenance-artifact-attestations\\">Build provenance: artifact attestations</h3>\\n      <p>\\n        For release binaries and images, generate a GitHub artifact\\n        attestation after the build and verify it at promotion or deployment.\\n        The workflow needs <code>id-token: write</code>,\\n        <code>attestations: write</code>, and least-privilege access to the\\n        artifact or package. <code>artifact-metadata: write</code> is\\n        additionally required when publishing storage records to the linked\\n        artifacts page. An attestation proves where and how an artifact was\\n        built; it does not replace tests, vulnerability scanning, or review.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"troubleshooting\\">\\n    <h2 id=\\"11-troubleshooting-as-an-admin\\">11) Troubleshooting as an admin</h2>\\n\\n    <div class=\\"box\\">\\n      <h3 id=\\"problem-ruleset-requires-aqua-scan-but-no-check-appears\\">Problem: \u201cRuleset requires Aqua scan but no check appears\u201d</h3>\\n      <ul>\\n        <li>Does the repo contain <code>.github/workflows/aqua-trivy-scan.yml</code>?</li>\\n        <li>Does it trigger on <code>pull_request</code> (not only on push)?</li>\\n        <li>Are GitHub Actions enabled at org/enterprise level for that repo?</li>\\n        <li>Does the workflow have conditions that skip it for some branches?</li>\\n        <li>Is the job failing before it reports a check (syntax errors, permission errors, runner issues)?</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box\\">\\n      <h3 id=\\"problem-i-required-aqua-trivy-scan-but-merges-still-blocked\\">Problem: \u201cI required aqua-trivy-scan but merges still blocked\u201d</h3>\\n      <ul>\\n        <li>Confirm the exact check name shown on PR (often <code>aqua-trivy-scan / scan</code>).</li>\\n        <li>Require the exact name in the ruleset.</li>\\n        <li>Ensure the check is not \u201cskipped\u201d or \u201cneutral\u201d for PRs.</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"box\\">\\n      <h3 id=\\"problem-self-hosted-runner-never-picks-up-jobs\\">Problem: \u201cSelf-hosted runner never picks up jobs\u201d</h3>\\n      <ul>\\n        <li>Is the runner online and registered?</li>\\n        <li>Does the workflow use the runner\u2019s labels in <code>runs-on</code>?</li>\\n        <li>Is the runner in a runner group that allows this repository?</li>\\n        <li>Do org policies restrict runner usage?</li>\\n      </ul>\\n    </div>\\n  </section>\\n\\n  <section id=\\"templates\\">\\n    <h2 id=\\"12-copy-paste-templates\\">12) Copy/paste templates</h2>\\n\\n    <h3 id=\\"12-1-minimal-workflow-skeleton\\">12.1 Minimal workflow skeleton</h3>\\n    <pre><code>name: example-workflow\\n\\non:\\n  pull_request:\\n\\npermissions:\\n  contents: read\\n\\njobs:\\n  job1:\\n    name: job1\\n    runs-on: ubuntu-24.04\\n    steps:\\n      - uses: actions/checkout@de0fac2e4500dabe0009e67214ff5f5447ce83dd  # v6.0.2\\n      - run: echo \\"hello\\"</code></pre>\\n\\n    <h3 id=\\"12-2-standardized-aqua-trivy-scan-workflow-recommended-naming\\">12.2 Standardized Aqua/Trivy scan workflow (recommended naming)</h3>\\n    <pre><code>name: aqua-trivy-scan\\n\\non:\\n  pull_request:\\n  push:\\n    branches: [ \\"main\\" ]\\n\\npermissions:\\n  contents: read\\n\\njobs:\\n  scan:\\n    name: scan\\n    runs-on: ubuntu-24.04\\n    steps:\\n      - uses: actions/checkout@de0fac2e4500dabe0009e67214ff5f5447ce83dd  # v6.0.2\\n      - uses: aquasecurity/trivy-action@ed142fd0673e97e23eac54620cfb913e5ce36c25  # v0.36.0\\n        with:\\n          scan-type: fs\\n          scan-ref: .\\n          severity: HIGH,CRITICAL\\n          exit-code: 1</code></pre>\\n\\n    <h3 id=\\"12-3-self-hosted-runner-selector\\">12.3 Self-hosted runner selector</h3>\\n    <pre><code>runs-on: [self-hosted, linux, x64, secure-runner]</code></pre>\\n\\n    <div class=\\"box ok\\">\\n      <p><strong>Final admin summary:</strong></p>\\n      <ul>\\n        <li>Workflows define what runs (<code>.github/workflows</code>).</li>\\n        <li>Runners execute jobs (<code>runs-on</code>).</li>\\n        <li>Jobs produce named checks (<code>workflow / job</code>).</li>\\n        <li>Rulesets enforce policy by requiring those checks and restricting push/merge behavior.</li>\\n      </ul>\\n    </div>\\n\\n    <h3 id=\\"12-4-supply-chain-verification-checklist\\">12.4 Supply-chain verification checklist</h3>\\n    <ul>\\n      <li>Resolve the release tag from the action\'s official repository and verify that the SHA belongs to that repository, not a fork.</li>\\n      <li>Review automated SHA-update PRs and the action\'s release/security notes before merging.</li>\\n      <li>Keep the default <code>GITHUB_TOKEN</code> permissions read-only and elevate only the job permissions that are required.</li>\\n      <li>Never check out untrusted pull-request code in a privileged <code>pull_request_target</code> job.</li>\\n      <li>Record and verify artifact attestations for promoted release artifacts.</li>\\n    </ul>\\n  </section>\\n\\n</main>\\n\\n<footer>\\n  <div class=\\"wrap\\">\\n    <p><strong>Scope.</strong> This chapter focuses on GitHub administration: rulesets, workflows/actions, runners, and enforcement behavior.</p>\\n    <p class=\\"tiny\\">Convert the enterprise baseline into a rollout matrix keyed by enterprise, organization, repository class, and branch pattern, with owners and exception-expiry dates.</p>\\n    <p class=\\"tiny\\"><strong>Official references:</strong>\\n      <a href=\\"https://docs.github.com/en/actions/reference/security/secure-use\\">Secure use of GitHub Actions</a> \xb7\\n      <a href=\\"https://docs.github.com/en/actions/reference/security/oidc\\">GitHub Actions OIDC claims</a> \xb7\\n      <a href=\\"https://docs.github.com/en/actions/concepts/security/artifact-attestations\\">Artifact attestations</a> \xb7\\n      <a href=\\"https://github.com/aquasecurity/trivy/security/advisories/GHSA-69fq-xp46-6x23\\">Trivy 2026 security advisory</a>\\n    </p>\\n  </div>\\n</footer>"}'),c={title:"GitHub Governance: Rulesets, Workflows, Runners, and Enforcement",slug:"/part2-backend-platform-security/14-github-governance",description:"A practical admin guide explaining what runs, who runs it, where it runs, and how GitHub blocks merges/pushes when policy is not satisfied.",sidebar_label:"16. GitHub governance and CI",pagination_label:"16. GitHub governance and CI",hide_title:!0,hide_table_of_contents:!0},l=void 0,d={},u=[];function h(e){return(0,o.jsx)(i.A,{content:a})}function p(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(h,{...e})}):h()}}}]);